#!/usr/bin/env bash
# Generated by node scripts/build-mcode-test-installer.mjs; edit the public installer or test-bootstrap.sh.
# 测试包配置和诊断入口；安装校验由同目录 install.sh 提供。
set -euo pipefail
umask 077

MCODE_TEST_VERSION='preview'
MCODE_TEST_TARBALL=''
diagnostic_stage='configuration'
diagnostic_id="${MCODE_SSH_DIAGNOSTIC_ID:-manual-$(date +%s)-$$}"
[[ "$diagnostic_id" =~ ^[0-9A-Za-z-]{1,80}$ ]] || diagnostic_id="manual-$(date +%s)-$$"
log_dir="$HOME/.minimax-code-test-logs"
mkdir -p "$log_dir"
chmod 700 "$log_dir"
log_path="$(mktemp "$log_dir/install-$(date +%Y%m%d-%H%M%S).XXXXXX")"
ln -sfn "$(basename "$log_path")" "$log_dir/latest.log"
find "$log_dir" -type f -name 'install-*' -mtime +7 -delete 2>/dev/null || true

redact_install_output() {
  LC_ALL=C awk '
    /-----BEGIN .*PRIVATE KEY-----/ { private_key = 1; print "[redacted private key]"; fflush() }
    private_key { if ($0 ~ /-----END .*PRIVATE KEY-----/) private_key = 0; next }
    {
      line = $0; lower = tolower(line)
      if (lower ~ /(bearer|basic)[[:space:]]|(authorization|cookie|_auth|api[-_]?key|token|password|secret|credential|signature)[[:alnum:]_-]*[^[:alnum:]]*[:=]/ ||
          lower ~ /[?&]sig=/ || line ~ /:\/\/[^\/[:space:]]+@|npm_[A-Za-z0-9]+|sk-[A-Za-z0-9_-]+|eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/)
        line = "[redacted credential-bearing line]"
      line = substr(line, 1, 16384)
      if (bytes < 1048576) { print line; bytes += length(line) + 1 }
      else {
        if (!limited++) print "[installer output truncated after 1 MiB]"
        if (line ~ /^\[mcode-test-install\]/ && summary_bytes < 16384) { print line; summary_bytes += length(line) + 1 }
      }
      fflush()
    }
  '
}

# 显式等待日志任务，兼容 macOS Bash 3，并在 SSH 完成帧之前刷新日志。
log_pipe="$log_path.pipe"
mkfifo "$log_pipe"
(redact_install_output < "$log_pipe" | tee -a "$log_path") &
log_pid=$!
exec 3>&1 4>&2
exec > "$log_pipe" 2>&1
rm "$log_pipe"
log_stage() {
  diagnostic_stage="$1"
  printf '[mcode-test-install] timestampMs=%s000 operationId=%s stage=%s\n' "$(date +%s)" "$diagnostic_id" "$diagnostic_stage"
}
test_installer_cleanup() {
  local status=$?
  trap - EXIT
  if declare -F cleanup >/dev/null; then cleanup || true; fi
  printf '[mcode-test-install] timestampMs=%s000 operationId=%s stage=%s exitCode=%s log=%s\n' \
    "$(date +%s)" "$diagnostic_id" "$diagnostic_stage" "$status" "$log_path"
  exec 1>&3 2>&4 3>&- 4>&-
  wait "$log_pid" || true
  exit "$status"
}
trap test_installer_cleanup EXIT
trap 'exit 130' HUP INT TERM
log_stage configuration
printf 'Installer log: %s\n' "$log_path"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --version|--prefix|--tarball)
      [[ $# -ge 2 && -n "$2" ]] || { printf 'error: %s requires a value\n' "$1" >&2; exit 1; }
      case "$1" in
        --version) MCODE_TEST_VERSION="$2" ;;
        --prefix) MCODE_INSTALL_DIR="$2" ;;
        --tarball) MCODE_TEST_TARBALL="$2" ;;
      esac
      shift 2 ;;
    -h|--help)
      printf '%s\n' 'Usage: bash install-mcode-test.sh [--version EXACT_PREVIEW] [--prefix DIRECTORY] [--tarball FILE]' \
        'Default: install @minimax/code@preview into ~/.minimax-code and add mcode to PATH.' \
        'Uses the public installer platform, Node bootstrap, checksum, native SQLite and activation checks.' \
        'A compatible private Node.js runtime is downloaded automatically when needed.' \
        'Logs: ~/.minimax-code-test-logs/latest.log (retained for 7 days).'
      exit 0 ;;
    *) printf 'error: Unknown option: %s\n' "$1" >&2; exit 1 ;;
  esac
done
[[ "$MCODE_TEST_VERSION" == preview || "$MCODE_TEST_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+-preview\.[0-9A-Za-z.-]+$ ]] || {
  printf 'error: Use preview or an exact preview version.\n' >&2; exit 1;
}
if [[ -n "$MCODE_TEST_TARBALL" ]]; then
  [[ "$MCODE_TEST_VERSION" != preview ]] || { printf 'error: --tarball requires --version EXACT_PREVIEW.\n' >&2; exit 1; }
  [[ -f "$MCODE_TEST_TARBALL" ]] || { printf 'error: The local package tarball does not exist.\n' >&2; exit 1; }
  MCODE_TEST_TARBALL="$(cd "$(dirname "$MCODE_TEST_TARBALL")" && pwd -P)/$(basename "$MCODE_TEST_TARBALL")"
fi
MCODE_INSTALL_DIR="${MCODE_INSTALL_DIR:-$HOME/.minimax-code}"
mkdir -p "$MCODE_INSTALL_DIR"
MCODE_INSTALL_DIR="$(cd "$MCODE_INSTALL_DIR" && pwd -P)"

# MiniMax Code CLI bootstrap installer for macOS, Linux, and WSL.
#
# Stable user command:
#   curl -fsSL <INSTALLER_URL>/install.sh | bash

set -euo pipefail

MCODE_PACKAGE_NAME='@minimax/code'
MCODE_INSTALL_DIR="${MCODE_INSTALL_DIR:-$HOME/.minimax-code}"
MCODE_NO_MODIFY_PATH="${MCODE_NO_MODIFY_PATH:-}"
