    ;;
  *)
    printf 'error: MCODE_DOWNLOAD_MIRROR must be cn, global, or empty\n' >&2
    exit 1
    ;;
esac
MCODE_NPM_REGISTRY="${MCODE_NPM_REGISTRY:-https://npmmirror.xaminim.com/}"
case "${MCODE_NPM_REGISTRY%/}" in
  https://npmmirror.xaminim.com)
    MCODE_NPM_REGISTRY="${MCODE_NPM_REGISTRY%/}/"
    ;;
  *)
    printf 'error: MCODE_NPM_REGISTRY must be npmmirror.xaminim.com\n' >&2
